#!/usr/bin/env bash
# Builds and runs the standalone rolling-shutter rows test.
#
# The library sources are compiled straight into the test binary, like
# tests/CMakeLists.txt does, so no installed library is needed.  OpenMP is
# left out here (the kernel is row-parallel but the test asserts output, not
# thread count); build with -DUSE_OMP if you want to exercise that path too.
set -euo pipefail
b=$(mktemp -d "${TMPDIR:-/tmp}/vidstab-rolling-rows.XXXXXX")
trap 'find "$b" -depth -delete' EXIT
cc=${CC:-cc}
# libvidstab.c includes the version header normally generated by CMake; fill
# the template from the same version.cmake the build uses.
major=$(sed -n 's/^set(MAJOR_VERSION \(.*\))$/\1/p' version.cmake)
minor=$(sed -n 's/^set(MINOR_VERSION \(.*\))$/\1/p' version.cmake)
patch=$(sed -n 's/^set(PATCH_VERSION \(.*\))$/\1/p' version.cmake)
sed -e "s/@MAJOR_VERSION@/$major/" -e "s/@MINOR_VERSION@/$minor/" \
    -e "s/@PATCH_VERSION@/$patch/" \
    src/libvidstab_version.h.in > "$b/libvidstab_version.h"
"$cc" -std=gnu99 -O2 -Wall -Wextra -Wno-pointer-sign -DVIDSTAB_STATIC_DEFINE \
  -I "$b" -I src -I tests \
  tests/rolling_rows.c tests/rolling_rows_ref.c \
  src/transform.c src/transformfixedpoint.c src/transformtype.c \
  src/frameinfo.c src/libvidstab.c src/vsvector.c src/lensmap.c \
  -o "$b/rolling_rows" -lm
"$b/rolling_rows"
